import java.util.*;

class Solution {
    public int searchInsert(int[] nums, int target) {
        int lo = 0, hi = nums.length;          // answer is in [0, n]
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < target) lo = mid + 1; // too small: answer is after mid
            else hi = mid;                        // mid might be the answer
        }
        return lo;                                // first index with value >= target
    }
}

